<?php
declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);require_once __DIR__.'/backup_lib.php';ts_schedule_auto_backup($pdo);}catch(Throwable $e){ts_log_internal($e,'SYS-101');ts_html_fail('SYS-101',503,'index.php');}
$currentAdmin=ts_require_roles($pdo,['owner','manager']);
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}
 $id=max(0,(int)($_POST['id']??0));$price=max(0,(int)($_POST['price']??0));$original=max(0,(int)($_POST['original_price']??0));
 if($original>0&&$price>=$original)$original=0;
 if($id){$st=$pdo->prepare('UPDATE products SET price=?,original_price=?,updated_at=NOW() WHERE id=? AND active=1');$st->execute([$price,$original?:null,$id]);$msg='قیمت و تخفیف ذخیره شد.';}
}
$products=$pdo->query('SELECT id,name,brand,quantity_label,image_path,price,original_price,stock FROM products WHERE active=1 ORDER BY (original_price IS NOT NULL AND original_price>price) DESC,name LIMIT 800')->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تخفیف‌ها</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:1050px;margin:20px auto;padding:0 12px}.prod{display:grid;grid-template-columns:64px 1fr 150px 150px auto;gap:10px;align-items:center;background:#fff;border:1px solid #e6ece7;border-radius:15px;padding:10px;margin:8px 0}.prod img{width:58px;height:58px;object-fit:contain}.off{display:inline-block;background:#e44532;color:#fff;border-radius:999px;padding:3px 8px;font-size:11px}@media(max-width:700px){.prod{grid-template-columns:52px 1fr}.prod img{width:48px;height:48px}.prod form{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr auto;gap:7px}.prod>.pricebox{display:none}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">💸</span><span><b>مدیریت تخفیف‌ها</b><small>قیمت اصلی و قیمت فروش</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php foreach($products as $p):$off=(!empty($p['original_price'])&&(int)$p['original_price']>(int)$p['price'])?round((1-(int)$p['price']/(int)$p['original_price'])*100):0;?><div class="prod"><?php if($p['image_path']):?><img src="<?=e($p['image_path'])?>" alt=""><?php else:?><div class="no-thumb">🛒</div><?php endif;?><div><b><?=e($p['name'])?></b><div class="muted"><?=e(trim(($p['brand']??'').' '.($p['quantity_label']??'')))?> · موجودی <?=number_format((int)$p['stock'])?></div><?php if($off>0):?><span class="off"><?=$off?>٪ تخفیف</span><?php endif;?></div><div class="pricebox"><?=number_format((int)$p['price'])?> تومان</div><div class="pricebox"><?=(int)$p['original_price']?number_format((int)$p['original_price']).' تومان':'بدون تخفیف'?></div><form method="post" style="display:flex;gap:7px;align-items:center"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><input type="number" name="price" min="0" value="<?=(int)$p['price']?>" title="قیمت فروش" required><input type="number" name="original_price" min="0" value="<?=(int)($p['original_price']??0)?>" title="قیمت اصلی"><button class="btn">ذخیره</button></form></div><?php endforeach;?></main></body></html>